export function cardArt(id, { className = 'card-art', label } = {}) {
  const key = Object.hasOwn(descriptions, id) ? id : 'unknown';
  const alt = label ?? descriptions[key];
  return '<img class="'+escape(className)+'" src="'+escape(assetURL('/assets/cards/'+key+'.svg'))+'" width="240" height="180" alt="'+escape(alt)+'" decoding="async" draggable="false">';
}
